'use client'

import { useId, type ReactNode, type Ref } from 'react'
import { Field } from '@base-ui/react/field'
import { Fieldset } from '@base-ui/react/fieldset'
import { Radio } from '@base-ui/react/radio'
import { RadioGroup as BaseRadioGroup } from '@base-ui/react/radio-group'
import { cn } from '@/lib/utils'
import { choiceStyles, type ValidationState } from './ChoiceField'
import styles from './Radio.module.css'

export interface RadioOption {
  value: string
  label: ReactNode
  helperText?: ReactNode
  disabled?: boolean
}

export interface RadioGroupProps {
  ref?: Ref<HTMLDivElement>
  options: RadioOption[]
  /** The group's legend. */
  label?: ReactNode
  /** Under the whole group; the error message when `validationState` is error. */
  helperText?: ReactNode
  value?: string
  defaultValue?: string
  /** The spec's `onChange`. Base UI's event details are dropped. */
  onValueChange?: (value: string) => void
  name?: string
  /** Colour of the selected radio. */
  variant?: 'primary' | 'neutral'
  orientation?: 'vertical' | 'horizontal'
  disabled?: boolean
  required?: boolean
  readOnly?: boolean
  validationState?: ValidationState
  className?: string
  'aria-label'?: string
}

/**
 * A set of radios, one of which is selected. A radio is meaningless alone —
 * arrow keys move within its group — so the component is the group, with
 * the radios as flat `options`.
 */
export function RadioGroup({
  ref,
  options,
  label,
  helperText,
  name,
  variant = 'neutral',
  orientation = 'vertical',
  disabled,
  required,
  validationState = 'default',
  className,
  onValueChange,
  ...props
}: RadioGroupProps) {
  // Plain help describes the group once. An error message goes through Field,
  // which puts it on every radio: whichever one has focus, the reader hears
  // what is wrong.
  const helperId = useId()
  const isError = validationState === 'error'
  return (
    <Field.Root
      name={name}
      disabled={disabled}
      invalid={isError}
      className={cn(choiceStyles.field, choiceStyles[validationState], styles.field, className)}
    >
      <Fieldset.Root
        render={
          <BaseRadioGroup
            {...props}
            ref={ref}
            aria-describedby={helperText && !isError ? helperId : undefined}
            required={required}
            onValueChange={onValueChange && ((next) => onValueChange(next as string))}
          />
        }
        className={cn(styles.group, styles[orientation])}
      >
        {label && (
          <Fieldset.Legend className={styles.legend}>
            {label}
            {required && (
              <span aria-hidden="true" className={choiceStyles.required}>
                *
              </span>
            )}
          </Fieldset.Legend>
        )}
        {options.map((option) => (
          <Field.Item key={option.value} disabled={option.disabled} className={styles.item}>
            <Field.Label className={choiceStyles.label}>
              <Radio.Root
                value={option.value}
                className={cn(choiceStyles.control, styles.radio, styles[variant])}
              >
                <Radio.Indicator className={styles.dot} />
              </Radio.Root>
              {option.label}
            </Field.Label>
            {option.helperText && (
              <Field.Description className={cn(choiceStyles.helper, styles.optionHelper)}>
                {option.helperText}
              </Field.Description>
            )}
          </Field.Item>
        ))}
      </Fieldset.Root>
      {helperText &&
        (isError ? (
          <Field.Description className={cn(choiceStyles.helper, styles.groupHelper)}>
            {helperText}
          </Field.Description>
        ) : (
          <p id={helperId} className={cn(choiceStyles.helper, styles.groupHelper)}>
            {helperText}
          </p>
        ))}
    </Field.Root>
  )
}

/* The circle is --choice-box: 16px, as Atlassian draws it. */
.field {
  --choice-control: var(--choice-box);
  gap: var(--space-2);
}

/* A fieldset carries browser padding, border and margin, and its legend is
   positioned by the browser; reset them so the group lays out like a grid. */
/* Vertical options are 4px apart: with a 20px label line that is one option
   every 24px, Atlassian's radio row, so the 24px hit areas meet and never
   overlap. */
.group {
  display: flex;
  gap: var(--space-1) var(--space-6);
  min-inline-size: 0;
  margin: 0;
  padding: 0;
  border: 0;
}
/* Two cases keep the wider 8px: an option with its own helper text, so the
   helper stays nearer its option than the next one; and touch screens, where
   the 44px hit areas would otherwise reach well into the neighbouring circle. */
.group:has(.optionHelper) {
  row-gap: var(--space-inline);
}
@media (pointer: coarse) {
  .group {
    row-gap: var(--space-inline);
  }
}

.vertical {
  flex-direction: column;
}

.horizontal {
  flex-flow: row wrap;
}

.legend {
  flex-basis: 100%;
  margin-block-end: var(--space-stack);
  padding: 0;
  font-size: var(--text-body);
  line-height: var(--leading-body);
  /* Atlassian's form Legend weight; an option's own label stays regular. */
  font-weight: var(--font-weight-label);
  color: var(--color-text);
}

.item {
  display: grid;
  gap: var(--space-stack);
}

/* An option's own helper describes the option, so it stays muted when the
   group is in error or success; only the group message takes that colour.
   Three classes to outrank ChoiceField's `.error .helper`. */
.item .optionHelper.optionHelper {
  color: var(--color-text-subtlest);
}

/* Group helper text sits under the group, not indented under a control. */
.groupHelper.groupHelper {
  padding-inline-start: 0;
}

/* --choice-box circle, a --color-border-bold outline (3:1 on the page). Selected fills
   with the variant and shows a dot in its label colour. */
.radio {
  --radio-fill: var(--color-text);
  --radio-dot: var(--color-surface);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  inline-size: var(--choice-control);
  block-size: var(--choice-control);
  border: 1px solid var(--color-border-bold);
  border-radius: var(--radius-pill);
  background: var(--color-surface);
  cursor: var(--cursor-button);
}

.primary {
  --radio-fill: var(--color-background-brand-bold);
  --radio-dot: var(--color-text-brand-inverse);
}

.radio[data-checked] {
  /* Transparent so the fill shows through the border and hover only has to
     change the background. */
  border-color: transparent;
  background: var(--radio-fill);
}

.radio[data-invalid] {
  border-color: var(--color-text-danger);
}

.radio[data-readonly] {
  cursor: default;
}

/* Hover anywhere on the option's label. Unselected darkens the ring (an
   error ring stays red); selected nudges the fill toward the dot, as Button
   does. */
label:hover > .radio:not([data-checked], [data-disabled], [data-readonly], [data-invalid]) {
  border-color: var(--color-text);
}

label:hover > .radio[data-checked]:not([data-disabled], [data-readonly]) {
  background: color-mix(in oklab, var(--radio-fill) 88%, var(--radio-dot));
}

/* 6px: a dot reads as "selected" without crowding the 16px ring. */
.dot {
  inline-size: var(--radio-dot-size);
  block-size: var(--radio-dot-size);
  border-radius: var(--radius-pill);
  background: var(--radio-dot);
}
